ALTER POLICY "gym photo editors insert" ON storage.objects WITH CHECK(bucket_id='gym-photos' AND EXISTS(SELECT 1 FROM public.gyms g WHERE g.id::text=(storage.foldername(objects.name))[1] AND public.has_gym_role(g.id,ARRAY['owner','manager']::public.app_role[])));
ALTER POLICY "gym photo editor read" ON storage.objects USING(bucket_id='gym-photos' AND EXISTS(SELECT 1 FROM public.gyms g WHERE g.id::text=(storage.foldername(objects.name))[1] AND public.has_gym_role(g.id,ARRAY['owner','manager']::public.app_role[])));
CREATE POLICY "gym photo editor delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='gym-photos' AND EXISTS(SELECT 1 FROM public.gyms g WHERE g.id::text=(storage.foldername(objects.name))[1] AND public.has_gym_role(g.id,ARRAY['owner','manager']::public.app_role[])));